{
  "findings": [
    {
      "check_id": "CKV_AZURE_52",
      "title": "Ensure MSSQL is using the latest version of TLS encryption",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The SQL server is not explicitly configured to enforce the latest version of TLS, which could expose it to vulnerabilities in older TLS versions."
    },
    {
      "check_id": "CKV_AZURE_113",
      "title": "Ensure that SQL server disables public network access",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "Public network access is not explicitly disabled, which could expose the SQL server to unauthorized access from the internet."
    },
    {
      "check_id": "CKV2_AZURE_27",
      "title": "Ensure Azure AD authentication is enabled for Azure SQL (MSSQL)",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "Azure AD authentication is not enabled, which is a more secure authentication method compared to SQL authentication."
    },
    {
      "check_id": "CKV2_AZURE_45",
      "title": "Ensure Microsoft SQL server is configured with private endpoint",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The SQL server is not configured with a private endpoint, which could expose it to public network traffic."
    },
    {
      "check_id": "CKV2_AZURE_2",
      "title": "Ensure that Vulnerability Assessment (VA) is enabled on a SQL server by setting a Storage Account",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "Vulnerability Assessment is not enabled, which could leave the SQL server vulnerable to misconfigurations and security risks."
    },
    {
      "check_id": "CKV_AZURE_23",
      "title": "Ensure that 'Auditing' is set to 'On' for SQL servers",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "Auditing is not enabled, which could result in a lack of visibility into database activities and potential security incidents."
    },
    {
      "check_id": "CKV_AZURE_24",
      "title": "Ensure that 'Auditing' Retention is 'greater than 90 days' for SQL servers",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "Auditing retention is not configured to be greater than 90 days, which could result in insufficient historical data for forensic analysis."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server\" \"changeme_simple_mssql_server\" {\n  name                         = \"changeme-simple-mssql-database-name\"\n  resource_group_name          = azurerm_resource_group.changeme_simple_mssql_server_resource_group.name\n  location                     = azurerm_resource_group.changeme_simple_mssql_server_resource_group.location\n  version                      = \"12.0\"\n  administrator_login          = \"changemeadmin\"\n  administrator_login_password = \"ch4ng3m3-A@Â£$%^&\"\n\n  minimum_tls_version          = \"1.2\"\n  public_network_access_enabled = false\n\n  azuread_administrator {\n    login_username = \"aad-admin@example.com\"\n    object_id      = \"00000000-0000-0000-0000-000000000000\"\n  }\n\n  extended_auditing_policy {\n    storage_endpoint                        = \"https://mystorageaccount.blob.core.windows.net/\"\n    storage_account_access_key             = \"<storage-account-access-key>\"\n    retention_in_days                      = 90\n  }\n\n  vulnerability_assessment {\n    storage_container_path = \"https://mystorageaccount.blob.core.windows.net/vulnerability-assessment/\"\n    storage_account_access_key = \"<storage-account-access-key>\"\n  }\n}\n\nresource \"azurerm_private_endpoint\" \"sql_private_endpoint\" {\n  name                = \"sql-private-endpoint\"\n  location            = azurerm_resource_group.changeme_simple_mssql_server_resource_group.location\n  resource_group_name = azurerm_resource_group.changeme_simple_mssql_server_resource_group.name\n\n  subnet_id = azurerm_subnet.example.id\n\n  private_service_connection {\n    name                           = \"sqlPrivateLink\"\n    private_connection_resource_id = azurerm_mssql_server.changeme_simple_mssql_server.id\n    is_manual_connection           = false\n    subresource_names              = [\"sqlServer\"]\n  }\n}",
  "fix_summary": "Configured the SQL server to enforce TLS 1.2, disable public network access, enable Azure AD authentication, set up auditing with retention greater than 90 days, enable vulnerability assessment with a storage account, and added a private endpoint for secure access."
}
